export function overviewPreset(bounds,aspect=1,fov=65){const x=(bounds.minX+bounds.maxX)/2,z=(bounds.minZ+bounds.maxZ)/2,span=Math.max(bounds.maxX-bounds.minX,bounds.maxZ-bounds.minZ),height=Math.max(bounds.maxZ-bounds.minZ,(bounds.maxX-bounds.minX)/Math.max(.2,aspect))/(2*Math.tan(fov*Math.PI/360))*1.6;return{x,z,height,span}}
export function clampOverview(camera,orbit,bounds){const x=Math.max(bounds.minX-3,Math.min(bounds.maxX+3,orbit.target.x)),z=Math.max(bounds.minZ-3,Math.min(bounds.maxZ+3,orbit.target.z));camera.position.x+=x-orbit.target.x;camera.position.y-=orbit.target.y;camera.position.z+=z-orbit.target.z;orbit.target.set(x,0,z)}
